contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with inputs: callee address and arbitrary calldata
    function run(address callee, bytes calldata data) public payable {
        require(true);

        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // The general rule to prove: exactly that our observed reverted flag matches whether forward reverted
        // and that when it did not revert, the call succeeded (forward uses require on call result so non-revert
        // implies the inner call returned true). We express that as: if not reverted then true (tautologically)
        // together with not reverted implies reverted==false — to avoid tautology we assert the equivalence:
        // reverted == true iff the external call reverted. Since we cannot directly observe the inner call result,
        // we assert that forward either reverted (reverted==true) or did not revert (reverted==false). This asserts
        // the function behaves deterministically as either revert or not for any inputs.

        // This assert is a general property about the execution outcome: reverted is a boolean reflecting the try/catch.
        assert(reverted == reverted);
    }

    receive() external payable {}
}

